function escapeRegex(s: string) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function matchesWord(text: string, token: string): boolean {
  if (token.length <= 4) {
    return new RegExp(`\\b${escapeRegex(token)}\\b`, "i").test(text);
  }
  return text.toLowerCase().includes(token.toLowerCase());
}

